import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { test } from "node:test";
import { assertSecretFree } from "./web/tests/e2e/leaks.mjs";
const source = readFileSync("web/tests/e2e/run.mjs", "utf8");
const schemas = JSON.parse(readFileSync("contracts/omnis.openapi.json", "utf8")).components.schemas;
const origin = "http://127.0.0.1:1", diagnosticPath = "/api/v1/diagnostics/ui-events";
const bodyStart = source.indexOf("function diagnosticBody(value) {");
const bodyEnd = source.indexOf("\nconst faultPath", bodyStart);
assert.ok(bodyStart >= 0 && bodyEnd > bodyStart);
const diagnosticBody = new Function("diagnosticContract", "assert", source.slice(bodyStart, bodyEnd) + ";return diagnosticBody;")(schemas, assert);
const predicate = source.match(/^function diagnosticPost\(request\).*$/m);
assert.ok(predicate);
const diagnosticPost = new Function("origin", "diagnosticPath", predicate[0] + ";return diagnosticPost;")(origin, diagnosticPath);
const start = source.indexOf("context.on(\u0027request\u0027, request => {");
const end = source.indexOf("\ncontext.on(\u0027page\u0027", start);
assert.ok(start >= 0 && end > start);
const register = new Function("context", "diagnosticPost", "diagnosticBody", "diagnosticEvents", "diagnosticTasks", "negativeDiagnostic", "diagnosticContract", "assert", "diagnosticReceipts", "diagnosticErrors", source.slice(start, end));
const id = "00000000-0000-4000-8000-000000000001";
const marker = "R2_SYNTHETIC_SECRET_MARKER_ONLY";
const event = {version:1, source:"browser_untrusted", event_id:id, surface:"brain_stream", site:"http_read", action:"ERROR", outcome:"UNCONFIRMED", error_code:null, correlation_id:id, run_id:null, command_id:null};
const ack = {version:1, event_id:id, accepted:true, state:"RECORDED"};
async function observe({ value=event, negative=null, correlation=id, status=202, bytes=JSON.stringify(ack), unavailable=false, url=origin+diagnosticPath, method="POST" }={}) {
  const handlers={}, events=new Map(), tasks=[], receipts=[], errors=[]; let reads=0;
  register({on(name, callback){assert.equal(handlers[name], undefined); handlers[name]=callback;}}, diagnosticPost, diagnosticBody, events, tasks, negative, schemas, assert, receipts, errors);
  const request={method:()=>method, url:()=>url, postDataJSON:()=>value};
  const response={request:()=>request, headers:()=>({"x-correlation-id":correlation}), status:()=>status, async body(){reads++; if(unavailable) throw new Error(marker); return Buffer.from(bytes);}};
  handlers.request(request); handlers.response(response); await Promise.all(tasks);
  return {events:[...events.values()], receipts, errors, reads};
}
test("actual request guard still rejects raw/free-text, unknown enums and invalid identities", async()=>{
  diagnosticBody(event);
  for(const value of [{...event,message:marker},{...event,surface:marker},{...event,error_code:marker},{...event,event_id:marker},{...event,run_id:marker}]) await assert.rejects(observe({value}));
});
test("actual negative probe remains excluded from event/receipt positives and body reads", async()=>{
  const value={...event,message:marker}, negative={id,secret:marker};
  const result=await observe({value,negative,status:422,correlation:null,unavailable:true});
  assert.deepEqual(result,{events:[],receipts:[],errors:[],reads:0});
  const wrongStatus=await observe({value,negative,status:202,unavailable:true});
  assert.deepEqual(wrongStatus,{events:[],receipts:[],errors:["INVALID_DIAGNOSTIC_ACK"],reads:0});
  await assert.rejects(observe({value:{...value,message:"wrong synthetic marker"},negative,status:422}));
});
test("unavailable-body error text cannot escape into receipt; fixture state is not an ACK state", async()=>{
  const result=await observe({unavailable:true});
  assert.deepEqual(result.receipts,[{event,request_correlation_id:id,state:"TRANSPORT_UNCONFIRMED"}]);
  assert.deepEqual(result.errors,[]); assert.equal(result.reads,1);
  assertSecretFree([marker],[JSON.stringify(result)]);
  assert.equal(schemas.UiAck.properties.state.enum.includes("TRANSPORT_UNCONFIRMED"),false);
  const spoof=await observe({bytes:JSON.stringify({...ack,state:"TRANSPORT_UNCONFIRMED"})});
  assert.deepEqual(spoof.receipts,[]); assert.deepEqual(spoof.errors,["INVALID_DIAGNOSTIC_ACK"]);
});
test("readable raw secret/malformed ACK and bad header remain only fixed error codes", async()=>{
  for(const options of [{bytes:marker},{bytes:JSON.stringify({...ack,extra:marker})},{correlation:marker,unavailable:true}]){
    const result=await observe(options);
    assert.deepEqual(result.receipts,[]); assert.deepEqual(result.errors,["INVALID_DIAGNOSTIC_ACK"]);
    assertSecretFree([marker],[JSON.stringify(result)]);
  }
});
test("exact POST predicate does not accept foreign origin, suffix, query, or HEAD", async()=>{
  for(const options of [{url:"http://127.0.0.1:2"+diagnosticPath},{url:origin+diagnosticPath+"/"},{url:origin+diagnosticPath+"?x=1"},{method:"HEAD"}]){
    const result=await observe(options); assert.deepEqual(result,{events:[],receipts:[],errors:[],reads:0});
  }
});
test("actual B04 source predicates cannot seed from transport uncertainty or wrong correlation", ()=>{
  const someLine=source.split("\n").find(line=>line.includes("check.poll(() => diagnosticReceipts.some("));
  const findLine=source.split("\n").find(line=>line.includes("const seed = diagnosticReceipts.find("));
  assert.ok(someLine && findLine);
  const someExpr=someLine.slice(someLine.indexOf("diagnosticReceipts.some("),someLine.lastIndexOf(").toBe(true)"));
  const findExpr=findLine.slice(findLine.indexOf("diagnosticReceipts.find("),findLine.lastIndexOf(".event;"));
  const hasSeed=new Function("diagnosticReceipts","failures","return "+someExpr);
  const findSeed=new Function("diagnosticReceipts","failures","return "+findExpr);
  const failures=new Set([id]);
  const transport={event,request_correlation_id:id,state:"TRANSPORT_UNCONFIRMED"};
  assert.equal(hasSeed([transport],failures),false); assert.equal(findSeed([transport],failures),undefined);
  const recorded={...transport,state:"RECORDED"};
  assert.equal(hasSeed([recorded],failures),true); assert.equal(findSeed([recorded],failures),recorded);
  assert.equal(hasSeed([{...recorded,event:{...event,correlation_id:"00000000-0000-4000-8000-000000000002"}}],failures),false);
  assert.equal(hasSeed([{...recorded,event:{...event,action:"REQUEST"}}],failures),false);
});
